package ncasa.shoppinglist.infrastructure.household;
import java.util.UUID;import ncasa.household.application.get.GetHouseholdMembershipContextUseCase;import ncasa.household.domain.*;import ncasa.shoppinglist.application.*;import ncasa.shoppinglist.application.port.out.ShoppingListHouseholdAccessPort;
public final class HouseholdShoppingListAccessAdapter implements ShoppingListHouseholdAccessPort{private final GetHouseholdMembershipContextUseCase memberships;public HouseholdShoppingListAccessAdapter(GetHouseholdMembershipContextUseCase m){memberships=m;}public ShoppingListHouseholdContext getContext(UUID household,Long actor){var c=memberships.execute(new HouseholdId(household),new AccountId(actor));return new ShoppingListHouseholdContext(c.actorMemberId(),c.activeMemberIds());}}
